template_max_run_s() {
    [[ -n "${_TPL_SOURCE_FILE:-}" && -f "${_TPL_SOURCE_FILE}" ]] || return 0
    awk '
        /^max_run_s:[[:space:]]/ {
            sub(/^max_run_s:[[:space:]]*/, "")
            sub(/[[:space:]]*#.*/, ""); gsub(/[[:space:]]/, "")
            print; exit
        }
    ' "${_TPL_SOURCE_FILE}" 2>/dev/null
}

